Lemma AEMShad_rd0 : forall m em e d a, AEMShad m em -> em_ok em -> em !! e = Some d -> e <= a < e + esize d ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr a 3 + 2147450880)) 1 = Some [b8 0].
Proof.
  intros m em e d a SH EOK L Ha. pose proof (em_ok_range _ _ _ EOK L) as (P & Q & R & _).
  eapply (acc8_rd0 m e (esize d) a); [eapply AEMShad_acc; [exact SH| exact EOK| exact L| lia| lia]| exact Q| exact (em_ok_al8 _ _ _ EOK L)| exact Ha].
Qed.

Lemma AHdrA_bounds : forall m h, AHdrA m h -> AIMG_TOP <= h /\ h + 48 <= aceil /\ h + 48 < 2^47 /\ 0 < h /\ h mod 8 = 0.
Proof.
  intros m h (AP & AL & _). pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  unfold AAPP_HI in *. repeat split; assumption.
Qed.

(* [comment removed for export] *)
Lemma ATreeR_node_cases : forall m h S ns em a nd, ATreeR m h S ns em -> ns !! a = Some nd ->
  a = h \/ exists d, em !! (a - 16) = Some d /\ 0 < a - 16 /\ a + 32 <= aceil.
Proof.
  intros m h S ns em a nd (NC & EC & RR & SK & DOM & EOK & ESH & HA & HS) L.
  destruct (DOM a) as [E|K]; [rewrite L; eexists; reflexivity| left; exact E|].
  destruct (em !! (a - 16)) as [d|] eqn:Ld; [| exfalso; exact (is_Some_None K)]. right. exists d. split; [reflexivity|].
  pose proof (em_ok_range _ _ _ EOK Ld) as (P & _ & R & _). pose proof (esize_ge d). lia.
Qed.
