Lemma ATreeR_S_payload : forall m h S ns em x, ATreeR m h S ns em -> x ∈ S ->
  exists d, em !! (x - 16) = Some d /\ rw_cells asegs m (x + 32) (ValCells d) /\ bytes_at asegs m (x + 40) (el_name d)
            /\ key_of em x = zbytes (el_name d) /\ elt_wf d /\ 0 < x - 16 /\ x - 16 + esize d <= aceil.
Proof.
  intros m h S ns em x (NC & EC & RR & SK & DOM & EOK & ESH & HA & HS) IN.
  destruct (em !! (x - 16)) as [d|] eqn:Ld. 2:{ exfalso. pose proof (SK x IN) as K. rewrite Ld in K. exact (is_Some_None K). }
  exists d. split; [reflexivity|].
  pose proof (AEMCells_node _ _ _ _ EC Ld) as C. split; [exact C|].
  split. { replace (x + 40) with (x + 32 + 8) by lia. apply ValCells_name_bytes. exact C. }
  split. { apply key_of_node. exact Ld. }
  pose proof (em_ok_range _ _ _ EOK Ld) as (P & _ & R & W). split; [exact W|]. lia.
Qed.

