(* [comment removed for export] *)
Lemma ANSCells_transport : forall W m m' ns,
  ANSCells m ns -> munch W m m' -> wmono asegs m m' ->
  (forall a nd, ns !! a = Some nd -> disjoint_from W a 32) -> ANSCells m' ns.
Proof.
  intros W m m' ns H MU WM D a nd L. destruct (H a nd L) as [WF [pad C]]. split; [exact WF|]. exists pad.
  eapply rw_cells_transport; [exact C| exact MU| exact WM|]. rewrite NodeCells_size. exact (D a nd L).
Qed.

Lemma ALSCells_transport : forall W m m' ls,
  ALSCells m ls -> munch W m m' -> wmono asegs m m' ->
  (forall a n, ls !! a = Some n -> disjoint_from W a 16) -> ALSCells m' ls.
Proof.
  intros W m m' ls H MU WM D a n L. destruct (H a n L) as [WF C]. split; [exact WF|].
  eapply rw_cells_transport; [exact C| exact MU| exact WM|]. rewrite LNodeCells_size. exact (D a n L).
Qed.

Lemma AEMCells_transport : forall W m m' em,
  AEMCells m em -> munch W m m' -> wmono asegs m m' ->
  (forall e d, em !! e = Some d -> disjoint_from W (e + 48) (esize d - 48)) -> AEMCells m' em.
Proof.
  intros W m m' em H MU WM D e d L.
  eapply rw_cells_transport; [exact (H e d L)| exact MU| exact WM|]. rewrite ValCells_size. exact (D e d L).
Qed.

(* [comment removed for export] *)
Lemma AEMShad_transport : forall W m m' em,
  AEMShad m em -> munch W m m' -> wmono asegs m m' ->
  (forall e d, em !! e = Some d -> disjoint_from W (sh e) (nsh (esize d))) -> AEMShad m' em.
Proof.
  intros W m m' em H MU WM D e d L. eapply addressable_transport; [exact (H e d L)| exact MU| exact WM| exact (D e d L)].
Qed.

Lemma AHdrA_transport : forall W m m' h,
  AHdrA m h -> munch W m m' -> (forall x, h <= x < h + 48 -> outside W (sh x)) -> AHdrA m' h.
Proof.
  intros W m m' h (AP & AL & AC) MU OUT. split; [exact AP|]. split; [exact AL|].
  eapply accessible_transport; [exact AC| exact MU| exact OUT].
Qed.

(* [comment removed for export] *)
Lemma AEMShad_transport_hi : forall W m m' em,
  AEMShad m em -> em_ok em -> munch W m m' -> wmono asegs m m' -> wins_hi W -> AEMShad m' em.
Proof.
  intros W m m' em H EOK MU WM WH e d L. pose proof (em_ok_aapp _ _ _ EOK L) as AP. pose proof (esize_ge d) as SG.
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  eapply addressable_transport_hi; [exact (H e d L)| exact MU| exact WM| lia| exact WH].
Qed.

Lemma AHdrA_transport_hi : forall W m m' h, AHdrA m h -> munch W m m' -> wins_hi W -> AHdrA m' h.
Proof.
  intros W m m' h (AP & AL & AC) MU WH. split; [exact AP|]. split; [exact AL|].
  eapply accessible_transport_hi; [exact AC| exact MU| exact WH].
Qed.

(* [comment removed for export] *)
Definition ns_out (ns : NS) (lo hi : Z) : Prop := forall a nd, ns !! a = Some nd -> a + 32 <= lo \/ hi <= a.

Lemma ANSCells_transport_out : forall W m m' ns lo hi,
  ANSCells m ns -> munch W m m' -> wmono asegs m m' -> ns_out ns lo hi ->
  Forall (fun iv : Z * Z => lo <= fst iv /\ snd iv <= hi) W -> ANSCells m' ns.
Proof.
  intros W m m' ns lo hi H MU WM OUT F. eapply ANSCells_transport; [exact H| exact MU| exact WM|].
  intros a nd L. pose proof (OUT a nd L) as K. clear -F K.
  induction W as [|[u v] W IH]; [exact I|]. cbn. pose proof (Forall_inv F) as K1. cbn in K1.
  split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.

Lemma ns_out_insert : forall ns lo hi a nd, ns_out ns lo hi -> (a + 32 <= lo \/ hi <= a) -> ns_out (<[a := nd]> ns) lo hi.
Proof.
  intros ns lo hi a nd H K b ndb Lb. destruct (Z.eq_dec b a) as [->|NE]; [exact K|].
  rewrite lookup_insert_ne in Lb by (intros E; apply NE; symmetry; exact E). exact (H b ndb Lb).
Qed.

Lemma ns_out_mono : forall ns lo hi lo' hi', ns_out ns lo hi -> lo <= lo' -> hi' <= hi -> ns_out ns lo' hi'.
Proof. intros ns lo hi lo' hi' H H1 H2 a nd L. destruct (H a nd L); lia. Qed.

(* [comment removed for export] *)
Definition stackW (SP : Z) (W : list (Z * Z)) : Prop :=
  Forall (fun iv : Z * Z => aceil <= fst iv /\ snd iv <= SP) W.

Lemma stackW_disjoint_low : forall SP W a n, stackW SP W -> a + n <= aceil -> disjoint_from W a n.
Proof.
  intros SP W a n F LE. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
  pose proof (Forall_inv F) as K. cbn in K. split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.

Lemma stackW_disjoint_high : forall SP W a n, stackW SP W -> SP <= a -> disjoint_from W a n.
Proof.
  intros SP W a n F LE. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
  pose proof (Forall_inv F) as K. cbn in K. split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.

Lemma stackW_wins_hi : forall SP W, stackW SP W -> wins_hi W.
Proof.
  intros SP W F. unfold wins_hi. eapply Forall_impl; [| exact F]. intros [l h] [K _]. cbn [fst snd] in *.
  right. pose proof aceil_facts as (AF & _). unfold AHI_LO. lia.
Qed.

Lemma stackW_nil : forall SP, stackW SP [].
Proof. intros SP. apply Forall_nil. Qed.

Lemma stackW_one : forall SP lo hi, aceil <= lo -> hi <= SP -> stackW SP [(lo, hi)].
Proof. intros SP lo hi H1 H2. apply Forall_cons; [cbn; lia| apply Forall_nil]. Qed.

(* [comment removed for export] *)
Lemma ATreeR_transport_gen : forall W m m' h S ns em,
  ATreeR m h S ns em -> munch W m m' -> wmono asegs m m' ->
  disjoint_from W h 48 -> (forall x, h <= x < h + 48 -> outside W (sh x)) ->
  (forall e d, em !! e = Some d -> disjoint_from W e (esize d) /\ disjoint_from W (sh e) (nsh (esize d))) ->
  ATreeR m' h S ns em.
Proof.
  intros W m m' h S ns em TR MU WM DH OH DE.
  pose proof TR as (NC & EC & RR & SK & DOM & EOK & ESH & HA & HS).
  split.
  { eapply ANSCells_transport; [exact NC| exact MU| exact WM|]. intros a nd L.
    destruct (DOM a) as [E|K]; [rewrite L; eexists; reflexivity| |].
    - subst a. eapply disjoint_from_sub; [exact DH| lia| lia].
    - destruct (em !! (a - 16)) as [d|] eqn:Ld; [| exfalso; exact (is_Some_None K)].
      pose proof (esize_ge d). eapply disjoint_from_sub; [exact (proj1 (DE _ _ Ld))| lia| lia]. }
  split.
  { eapply AEMCells_transport; [exact EC| exact MU| exact WM|]. intros e d L.
    pose proof (esize_ge d). eapply disjoint_from_sub; [exact (proj1 (DE _ _ L))| lia| lia]. }
  split; [exact RR|]. split; [exact SK|]. split; [exact DOM|]. split; [exact EOK|].
  split. { eapply AEMShad_transport; [exact ESH| exact MU| exact WM|]. intros e d L. exact (proj2 (DE _ _ L)). }
  split; [| exact HS]. eapply AHdrA_transport; [exact HA| exact MU| exact OH].
Qed.

Lemma AFieldsC_node_in : forall m Fa S L ns ls em a nd, AFieldsC m Fa S L ns ls em -> ns !! a = Some nd ->
  a = Fa \/ exists d, em !! (a - 16) = Some d /\ a - 16 ∈ L.
Proof.
  intros m Fa S L ns ls em a nd (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS) La.
  destruct (proj1 (rb_ok_dom _ _ _ a OK)) as [E|IN]; [rewrite La; eexists; reflexivity| left; exact E|].
  right. pose proof (proj1 SL a IN) as INL. pose proof (proj1 (LE _) INL) as K.
  destruct (em !! (a - 16)) as [d|] eqn:Ld; [| exfalso; exact (is_Some_None K)].
  exists d. split; [reflexivity| exact INL].
Qed.

Lemma AFieldsC_lnode_in : forall m Fa S L ns ls em a n, AFieldsC m Fa S L ns ls em -> ls !! a = Some n ->
  a = Fa + 32 \/ exists d, em !! a = Some d /\ a ∈ L.
Proof.
  intros m Fa S L ns ls em a n (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS) La.
  destruct DL as (ND & DOM & NXT).
  assert (K : a ∈ Fa + 32 :: L). { apply DOM. rewrite La. eexists; reflexivity. }
  rewrite elem_of_cons in K. destruct K as [E|IN]; [left; exact E| right].
  pose proof (proj1 (LE _) IN) as K. destruct (em !! a) as [d|] eqn:Ld; [| exfalso; exact (is_Some_None K)].
  exists d. split; [reflexivity| exact IN].
Qed.
