(* [comment removed for export] *)
Definition fwin (Fa : Z) (em : gmap Z elt) (iv : Z * Z) : Prop :=
  ((AIMG_TOP <= fst iv /\ snd iv <= ALOWSH_LO) \/ AHI_LO <= fst iv)
  /\ (snd iv <= Fa \/ Fa + 48 <= fst iv)
  /\ (forall e d, em !! e = Some d -> snd iv <= e \/ e + esize d <= fst iv).

Lemma fwin_wins_hi : forall Fa em W, Forall (fwin Fa em) W -> wins_hi W.
Proof. intros Fa em W F. unfold wins_hi. eapply Forall_impl; [| exact F]. intros iv (K & _). exact K. Qed.

Lemma fwin_disjoint_hdr : forall Fa em W a n, Forall (fwin Fa em) W -> Fa <= a -> a + n <= Fa + 48 -> disjoint_from W a n.
Proof.
  intros Fa em W a n F H1 H2. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
  pose proof (Forall_inv F) as (_ & K & _). cbn in K. split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.

Lemma fwin_disjoint_elt : forall Fa em W e d a n, Forall (fwin Fa em) W -> em !! e = Some d ->
  e <= a -> a + n <= e + esize d -> disjoint_from W a n.
Proof.
  intros Fa em W e d a n F L H1 H2. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
  pose proof (Forall_inv F) as (_ & _ & K). specialize (K e d L). cbn in K.
  split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.

(* [comment removed for export] *)
Lemma fwin_stack : forall m Fa em lo hi, AHdrA m Fa -> em_ok em -> aceil <= lo -> fwin Fa em (lo, hi).
Proof.
  intros m Fa em lo hi HA EOK CE. pose proof (AHdrA_bounds _ _ HA) as (B1 & B2 & _). pose proof aceil_facts as (AF & _).
  split; [right; cbn; unfold AHI_LO; lia|]. split; [right; cbn; lia|].
  intros e d L. pose proof (em_ok_range _ _ _ EOK L) as (_ & _ & R & _). right. cbn. lia.
Qed.

