Lemma stackW_fwin : forall m SP W Fa em, stackW SP W -> AHdrA m Fa -> em_ok em -> Forall (fwin Fa em) W.
Proof.
  intros m SP W Fa em F HA EOK. eapply Forall_impl; [| exact F]. intros [l h] [K _]. cbn [fst snd] in K.
  eapply fwin_stack; eauto.
Qed.

(* [comment removed for export] *)
Lemma ATreeR_transport : forall SP W m m' h S ns em,
  ATreeR m h S ns em -> munch W m m' -> wmono asegs m m' -> stackW SP W -> ATreeR m' h S ns em.
Proof.
  intros SP W m m' h S ns em TR MU WM SW. pose proof TR as (_ & _ & _ & _ & _ & EOK & _ & HA & _).
  eapply ATreeR_transport_win; [exact TR| exact MU| exact WM| eapply stackW_fwin; eauto].
Qed.

Lemma AFieldsC_transport : forall SP W m m' Fa S L ns ls em,
  AFieldsC m Fa S L ns ls em -> munch W m m' -> wmono asegs m m' -> stackW SP W ->
  AFieldsC m' Fa S L ns ls em.
Proof.
  intros SP W m m' Fa S L ns ls em FC MU WM SW. pose proof FC as (_ & _ & _ & _ & _ & _ & _ & _ & EOK & _ & HA & _).
  eapply AFieldsC_transport_win; [exact FC| exact MU| exact WM| eapply stackW_fwin; eauto].
Qed.

(* [comment removed for export] *)
Lemma ATreeR_ns_out : forall m h S ns em lo hi, ATreeR m h S ns em -> aceil <= lo -> ns_out ns lo hi.
Proof.
  intros m h S ns em lo hi TR LO a nd L.
  destruct (ATreeR_node_acc _ _ _ _ _ _ _ TR L) as (_ & AP & _).
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (_ & B2 & _). left. lia.
Qed.

(* [comment removed for export] *)
Lemma AFieldsC_TreeR : forall m Fa S L ns ls em, AFieldsC m Fa S L ns ls em -> ATreeR m Fa S ns em.
Proof.
  intros m Fa S L ns ls em (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  split; [exact NC|]. split; [exact EC|]. split; [apply rb_ok_rep; exact OK|].
  split. { intros x IN. apply LE. apply (proj1 SL). exact IN. }
  split. { intros a Ha. destruct (proj1 (rb_ok_dom _ _ _ a OK) Ha) as [E|IN].
           { left; exact E. } { right. apply LE. apply (proj1 SL). exact IN. } }
  split; [exact EOK|]. split; [exact ESH|]. split; [exact HA| exact HS].
Qed.

Lemma AFieldsC_sorted : forall m Fa S L ns ls em, AFieldsC m Fa S L ns ls em -> sorted key_lt (key_of em) S.
Proof. intros m Fa S L ns ls em FC. exact (proj1 (proj2 (proj2 (proj2 (proj2 FC))))). Qed.

Lemma AFieldsC_rb_ok : forall m Fa S L ns ls em, AFieldsC m Fa S L ns ls em -> rb_ok Fa S ns.
Proof. intros m Fa S L ns ls em FC. exact (proj1 (proj2 (proj2 (proj2 FC)))). Qed.

Lemma AFieldsC_dl_ok : forall m Fa S L ns ls em, AFieldsC m Fa S L ns ls em -> dl_ok (Fa + 32) L ls.
Proof. intros m Fa S L ns ls em FC. exact (proj1 (proj2 (proj2 (proj2 (proj2 (proj2 FC)))))). Qed.

Lemma AFieldsC_S_L : forall m Fa S L ns ls em, AFieldsC m Fa S L ns ls em -> forall x, x ∈ S -> x - 16 ∈ L.
Proof. intros m Fa S L ns ls em FC. exact (proj1 (proj1 (proj2 (proj2 (proj2 (proj2 (proj2 (proj2 FC)))))))). Qed.

