(* [comment removed for export] *)
Lemma AFieldsC_node_cases : forall m Fa S L ns ls em a nd, AFieldsC m Fa S L ns ls em -> ns !! a = Some nd ->
  a = Fa \/ exists d, em !! (a - 16) = Some d /\ a - 16 ∈ L /\ 0 < a - 16 /\ (a - 16) mod 8 = 0 /\ a - 16 + esize d <= aceil
                      /\ (a - 16 + esize d <= Fa \/ Fa + 48 <= a - 16).
Proof.
  intros m Fa S L ns ls em a nd FC La. pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  destruct (AFieldsC_node_in _ _ _ _ _ _ _ _ _ FC La) as [E|(d & Ld & INL)]; [left; exact E| right].
  exists d. split; [exact Ld|]. split; [exact INL|]. pose proof (em_ok_range _ _ _ EOK Ld) as (P & Q & R & _).
  split; [exact P|]. split; [exact Q|]. split; [exact R| exact (HS _ _ Ld)].
Qed.

Lemma AFieldsC_lnode_cases : forall m Fa S L ns ls em a n, AFieldsC m Fa S L ns ls em -> ls !! a = Some n ->
  a = Fa + 32 \/ exists d, em !! a = Some d /\ a ∈ L /\ 0 < a /\ a mod 8 = 0 /\ a + esize d <= aceil
                           /\ (a + esize d <= Fa \/ Fa + 48 <= a).
Proof.
  intros m Fa S L ns ls em a n FC La. pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  destruct (AFieldsC_lnode_in _ _ _ _ _ _ _ _ _ FC La) as [E|(d & Ld & INL)]; [left; exact E| right].
  exists d. split; [exact Ld|]. split; [exact INL|]. pose proof (em_ok_range _ _ _ EOK Ld) as (P & Q & R & _).
  split; [exact P|]. split; [exact Q|]. split; [exact R| exact (HS _ _ Ld)].
Qed.

Lemma AFieldsC_ns_sep : forall m Fa S L ns ls em, AFieldsC m Fa S L ns ls em -> ns_sep ns.
Proof.
  intros m Fa S L ns ls em FC a b nda ndb La Lb NE.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  destruct (AFieldsC_node_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(da & Lda & _ & Pa & _ & Ra & Ha)];
  destruct (AFieldsC_node_cases _ _ _ _ _ _ _ _ _ FC Lb) as [->|(db & Ldb & _ & Pb & _ & Rb & Hb)].
  - exfalso. exact (NE eq_refl).
  - pose proof (esize_ge db). lia.
  - pose proof (esize_ge da). lia.
  - pose proof (esize_ge da). pose proof (esize_ge db).
    destruct (em_ok_disj _ _ _ _ _ EOK Lda Ldb ltac:(intros E; apply NE; lia)); lia.
Qed.

