Lemma AFieldsC_node_lnode_disj : forall m Fa S L ns ls em a nd b n,
  AFieldsC m Fa S L ns ls em -> ns !! a = Some nd -> ls !! b = Some n -> a + 32 <= b \/ b + 16 <= a.
Proof.
  intros m Fa S L ns ls em a nd b n FC La Lb.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  destruct (AFieldsC_node_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(da & Lda & _ & Pa & _ & Ra & Ha)];
  destruct (AFieldsC_lnode_cases _ _ _ _ _ _ _ _ _ FC Lb) as [->|(db & Ldb & _ & Pb & _ & Rb & Hb)].
  - lia.
  - pose proof (esize_ge db). lia.
  - pose proof (esize_ge da). lia.
  - pose proof (esize_ge da). pose proof (esize_ge db).
    destruct (Z.eq_dec (a - 16) b) as [E|NE]; [lia|].
    destruct (em_ok_disj _ _ _ _ _ EOK Lda Ldb NE); lia.
Qed.

Lemma AFieldsC_node_payload_disj : forall m Fa S L ns ls em a nd e d,
  AFieldsC m Fa S L ns ls em -> ns !! a = Some nd -> em !! e = Some d -> a + 32 <= e + 48 \/ e + esize d <= a.
Proof.
  intros m Fa S L ns ls em a nd e d FC La Le.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  pose proof (em_ok_range _ _ _ EOK Le) as (Pe & _ & Re & _). pose proof (esize_ge d). pose proof (HS _ _ Le) as He.
  destruct (AFieldsC_node_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(da & Lda & _ & Pa & _ & Ra & Ha)]; [lia|].
  destruct (Z.eq_dec (a - 16) e) as [E|NE]; [lia|]. pose proof (esize_ge da).
  destruct (em_ok_disj _ _ _ _ _ EOK Lda Le NE); lia.
Qed.

Lemma AFieldsC_lnode_payload_disj : forall m Fa S L ns ls em b n e d,
  AFieldsC m Fa S L ns ls em -> ls !! b = Some n -> em !! e = Some d -> b + 16 <= e + 48 \/ e + esize d <= b.
Proof.
  intros m Fa S L ns ls em b n e d FC Lb Le.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  pose proof (em_ok_range _ _ _ EOK Le) as (Pe & _ & Re & _). pose proof (esize_ge d). pose proof (HS _ _ Le) as He.
  destruct (AFieldsC_lnode_cases _ _ _ _ _ _ _ _ _ FC Lb) as [->|(db & Ldb & _ & Pb & _ & Rb & Hb)]; [lia|].
  destruct (Z.eq_dec b e) as [E|NE]; [lia|]. pose proof (esize_ge db).
  destruct (em_ok_disj _ _ _ _ _ EOK Ldb Le NE); lia.
Qed.

