Lemma nacc_rd0 : forall m a, accessible m a 32 -> a mod 8 = 0 ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr a 3 + 2147450880)) 1 = Some [b8 0].
Proof. intros m a AC AL. pose proof (nacc_rd m a 0 AC AL ltac:(lia)) as K. rewrite Z.add_0_r in K. exact K. Qed.

(* [comment removed for export] *)
Definition ANSAcc (m : mem) (ns : NS) : Prop :=
  forall a nd, ns !! a = Some nd -> a mod 8 = 0 /\ aapp a 32 /\ accessible m a 32.

Lemma ATreeR_nsacc : forall m h S ns em, ATreeR m h S ns em -> ANSAcc m ns.
Proof. intros m h S ns em TR a nd L. exact (ATreeR_node_acc _ _ _ _ _ _ _ TR L). Qed.

Lemma AFieldsC_nsacc : forall m Fa S L ns ls em, AFieldsC m Fa S L ns ls em -> ANSAcc m ns.
Proof. intros m Fa S L ns ls em FC a nd La. exact (AFieldsC_node_acc _ _ _ _ _ _ _ _ _ FC La). Qed.

Lemma ANSAcc_rd : forall m ns a nd k, ANSAcc m ns -> ns !! a = Some nd -> (k = 0 \/ k = 8 \/ k = 16 \/ k = 24) ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr (a + k) 3 + 2147450880)) 1 = Some [b8 0].
Proof. intros m ns a nd k NA L Hk. destruct (NA a nd L) as (AL & _ & AC). exact (nacc_rd m a k AC AL Hk). Qed.

Lemma ANSAcc_rd0 : forall m ns a nd, ANSAcc m ns -> ns !! a = Some nd ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr a 3 + 2147450880)) 1 = Some [b8 0].
Proof. intros m ns a nd NA L. destruct (NA a nd L) as (AL & _ & AC). exact (nacc_rd0 m a AC AL). Qed.

Lemma ANSAcc_bounds : forall m ns a nd, ANSAcc m ns -> ns !! a = Some nd ->
  a mod 8 = 0 /\ AIMG_TOP <= a /\ a + 32 <= aceil /\ a + 32 < 2^47 /\ 0 < a.
Proof.
  intros m ns a nd NA L. destruct (NA a nd L) as (AL & AP & _). pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  unfold AAPP_HI in *. repeat split; assumption.
Qed.

Lemma ANSAcc_ns_out : forall m ns lo hi, ANSAcc m ns -> aceil <= lo -> ns_out ns lo hi.
Proof. intros m ns lo hi NA LO a nd L. pose proof (ANSAcc_bounds _ _ _ _ NA L) as (_ & _ & B & _). left. lia. Qed.

Lemma ANSAcc_transport_hi : forall W m m' ns, ANSAcc m ns -> munch W m m' -> wins_hi W -> ANSAcc m' ns.
Proof.
  intros W m m' ns NA MU WH a nd L. destruct (NA a nd L) as (AL & AP & AC). split; [exact AL|]. split; [exact AP|].
  eapply accessible_transport_hi; [exact AC| exact MU| exact WH].
Qed.

(* [comment removed for export] *)
Lemma ANSAcc_update : forall m ns a nd', ANSAcc m ns -> is_Some (ns !! a) -> ANSAcc m (<[ a := nd' ]> ns).
Proof.
  intros m ns a nd' NA [nd L] b ndb Lb. destruct (Z.eq_dec b a) as [->|NE].
  - exact (NA a nd L).
  - rewrite lookup_insert_ne in Lb by (intros E; apply NE; symmetry; exact E). exact (NA b ndb Lb).
Qed.

Lemma ANSAcc_insert : forall m ns a nd, ANSAcc m ns -> a mod 8 = 0 -> aapp a 32 -> accessible m a 32 -> ANSAcc m (<[ a := nd ]> ns).
Proof.
  intros m ns a nd NA AL AP AC b ndb Lb. destruct (Z.eq_dec b a) as [->|NE].
  - split; [exact AL|]. split; [exact AP| exact AC].
  - rewrite lookup_insert_ne in Lb by (intros E; apply NE; symmetry; exact E). exact (NA b ndb Lb).
Qed.

(* [comment removed for export] *)
Lemma ANS_frame : forall SP W m m' ns,
  ANSCells m ns -> ANSAcc m ns -> munch W m m' -> wmono asegs m m' -> stackW SP W -> ANSCells m' ns /\ ANSAcc m' ns.
Proof.
  intros SP W m m' ns NC NA MU WM SW. split.
  - eapply ANSCells_transport; [exact NC| exact MU| exact WM|]. intros a nd L.
    pose proof (ANSAcc_bounds _ _ _ _ NA L) as (_ & _ & B & _). eapply stackW_disjoint_low; [exact SW| exact B].
  - eapply ANSAcc_transport_hi; [exact NA| exact MU| exact (stackW_wins_hi _ _ SW)].
Qed.

